// === Метрики постов конкурента. Реализует правила 1.1–1.5 в коде, а не в LLM ===
const NEIGHBORS = 2;          // соседей с каждой стороны (2 до + 2 после)
const NOTABLE_RATIO = 2.0;    // отношение к медиане соседей: >= это = «заметный»
const OUTLIER_RATIO = 3.0;    // >= это = «выброс»
const FULL_TEXT_CHARS = 1200; // сколько символов текста давать по notable-посту

// 1) достаём items из ответа wall.get (учёт обёртки-массива)
let root = $input.first().json;
if (Array.isArray(root)) root = root[0];
const resp = root.response || root;
const items = (resp.items || []).slice();

// 2) охват поста с учётом клипов (правило 1.3)
function reachOf(p) {
  const atts = p.attachments || [];
  const clips = atts
    .filter(a => a.type === 'video' && a.video && a.video.type === 'short_video')
    .map(a => a.video.views || a.video.local_views || 0);
  if (clips.length) return Math.max(...clips);   // клип → просмотры клипа
  return (p.views && p.views.count) || 0;         // обычный пост → views.count
}

// 3) вовлечённость (правило 1.2)
function erOf(p, reach) {
  const likes = (p.likes && p.likes.count) || (p.reactions && p.reactions.count) || 0;
  const comments = (p.comments && p.comments.count) || 0;
  const reposts = (p.reposts && p.reposts.count) || 0;
  if (!reach) return 0;
  return (likes + comments + reposts) / reach;
}

// 4) причина исключения из СТАТИСТИКИ приёмов (правило 1.5). Из окна соседей НЕ убираем.
function excludeReason(p) {
  const text = (p.text || '').trim();
  if (p.marked_as_ads === 1) return 'ads';
  if (p.copy_history) return 'repost';
  if (!text) return 'empty_text';
  if (/розыгрыш|конкурс|репост.*участи|приз/i.test(text)) return 'giveaway_maybe';
  return null;
}

// 5) сортировка по времени и базовые метрики
items.sort((a, b) => a.date - b.date);
const rows = items.map(p => {
  const reach = reachOf(p);
  const fullText = (p.text || '').trim();
  return {
    id: p.id,
    date: p.date,
    date_h: new Date(p.date * 1000).toISOString().slice(0, 10),
    first_line: fullText.split('\n')[0].slice(0, 200),
    _full: fullText,                 // временно, срежем ниже под notable
    text_len: fullText.length,
    is_clip: (p.attachments || []).some(a => a.type === 'video' && a.video && a.video.type === 'short_video'),
    reach,
    er: +erOf(p, reach).toFixed(4),
    likes: (p.likes && p.likes.count) || (p.reactions && p.reactions.count) || 0,
    comments: (p.comments && p.comments.count) || 0,
    reposts: (p.reposts && p.reposts.count) || 0,
    exclude: excludeReason(p),
  };
});

// 6) медиана 4 соседей и отношение (правило 1.1). Соседи — ВСЕ посты в окне.
function median(arr) {
  if (!arr.length) return 0;
  const s = arr.slice().sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
}
rows.forEach((r, i) => {
  const nb = [];
  for (let k = i - NEIGHBORS; k <= i + NEIGHBORS; k++) {
    if (k === i || k < 0 || k >= rows.length) continue;
    nb.push(rows[k].reach);
  }
  const med = median(nb);
  r.neighbor_median = med;
  r.ratio = med ? +(r.reach / med).toFixed(2) : null;
  r.notable = r.ratio != null && r.ratio >= NOTABLE_RATIO && !r.exclude;
  r.outlier = r.ratio != null && r.ratio >= OUTLIER_RATIO && !r.exclude;
});

// 7) полный текст даём ТОЛЬКО notable-постам (они идут в приёмы), остальным — срезаем
rows.forEach(r => {
  if (r.notable) r.text = r._full.slice(0, FULL_TEXT_CHARS);
  delete r._full;
});

// 8) итог для Аналитика
const period = rows.length ? `${rows[0].date_h} – ${rows[rows.length - 1].date_h}` : '';
const excluded_count = rows.filter(r => r.exclude).length;

return [{
  json: {
    period,
    total: rows.length,
    excluded_count,
    notable_count: rows.filter(r => r.notable).length,
    posts: rows,
  }
}];

